cat > src/cli.rs << 'EOF'
use clap::Parser;

#[derive(Parser, Debug, Clone)]
#[command(name = "igrep")]
#[command(about = "Interactive Grep", long_about = None)]
#[command(version = "1.3.0")]
pub struct Args {
    /// Regular expression used for searching
    #[arg(value_name = "PATTERN")]
    pub pattern: Option<String>,

    /// Files or directories to search. Directories are searched recursively.
    /// If not specified, searching starts from current directory.
    #[arg(value_name = "PATHS")]
    pub paths: Vec<String>,

    /// Text editor used to open selected match
    #[arg(long, value_name = "EDITOR")]
    pub editor: Option<String>,

    /// Custom command used to open selected match. Must contain {file_name} and {line_number} tokens
    #[arg(long, value_name = "CUSTOM_COMMAND", env = "IGREP_CUSTOM_EDITOR")]
    pub custom_command: Option<String>,

    /// UI color theme
    #[arg(long, value_name = "THEME", default_value = "dark")]
    pub theme: String,

    /// Searches case insensitively
    #[arg(short, long)]
    pub ignore_case: bool,

    /// Searches case insensitively if the pattern is all lowercase
    #[arg(short = 'S', long)]
    pub smart_case: bool,

    /// Search hidden files and directories
    #[arg(short = '.', long)]
    pub hidden: bool,

    /// Follow symbolic links while traversing directories
    #[arg(short = 'L', long)]
    pub follow: bool,

    /// Only show matches surrounded by word boundaries
    #[arg(short, long)]
    pub word_regexp: bool,

    /// Exact matches with no regex
    #[arg(short = 'F', long)]
    pub fixed_strings: bool,

    /// Search with pattern contains newline character
    #[arg(short = 'U', long)]
    pub multiline: bool,

    /// Include files and directories matching the given glob
    #[arg(short, long, value_name = "GLOB")]
    pub glob: Vec<String>,

    /// Show all supported file types and their corresponding globs
    #[arg(long)]
    pub type_list: bool,

    /// Only search files matching TYPE
    #[arg(short = 't', long, value_name = "TYPE_MATCHING")]
    pub r#type: Vec<String>,

    /// Do not search files matching TYPE
    #[arg(short = 'T', long, value_name = "TYPE_NOT")]
    pub type_not: Vec<String>,

    /// Context viewer position at startup
    #[arg(long, value_name = "CONTEXT_VIEWER", default_value = "none")]
    pub context_viewer: String,

    /// Sort results
    #[arg(long, value_name = "SORT_BY")]
    pub sort: Option<String>,

    /// Sort results reverse
    #[arg(long, value_name = "SORT_BY_REVERSE")]
    pub sortr: Option<String>,

    /// Print help
    #[arg(short, long)]
    pub help: bool,

    /// Print version
    #[arg(short = 'V', long)]
    pub version: bool,
}
EOF

