pub fn print_type_list() {
    let types = get_file_types();
    let mut sorted_types: Vec<_> = types.iter().collect();
    sorted_types.sort_by_key(|&(k, _)| k);

    for (name, globs) in sorted_types {
        let glob_str = globs.join(", ");
        println!("{}: {}", name, glob_str);
    }
}
