use anyhow::Result;
use regex::Regex;
use std::path::PathBuf;
use std::fs;
use walkdir::WalkDir;
use crate::cli::Args;

#[derive(Debug, Clone)]
pub struct Match {
    pub file_path: PathBuf,
    pub line_number: usize,
    pub line_text: String,
    pub match_start: usize,
    pub match_end: usize,
}

pub struct SearchResults {
    pub matches: Vec<Match>,
}

pub fn search(args: &Args) -> Result<SearchResults> {
    let pattern = args.pattern.as_ref().ok_or(anyhow::anyhow!("Pattern required"))?;

    // Compile regex
    let regex = if args.fixed_strings {
        Regex::new(&regex::escape(pattern))?
    } else {
        let flags = if args.ignore_case || (args.smart_case && pattern.chars().all(|c| c.is_lowercase())) {
            format!("(?i){}", pattern)
        } else {
            pattern.to_string()
        };
        Regex::new(&flags)?
    };

    // Get search paths
    let search_paths = if args.paths.is_empty() {
        vec![".".to_string()]
    } else {
        args.paths.clone()
    };

    let mut matches = Vec::new();

    // Search through files
    for search_path in search_paths {
        let path = PathBuf::from(&search_path);

        if path.is_file() {
            search_file(&path, &regex, &mut matches, args)?;
        } else if path.is_dir() {
            search_directory(&path, &regex, &mut matches, args)?;
        }
    }

    Ok(SearchResults { matches })
}

fn search_file(path: &PathBuf, regex: &Regex, matches: &mut Vec<Match>, args: &Args) -> Result<()> {
    // Check if file should be searched based on type filters
    if !should_search_file(path, args) {
        return Ok(());
    }

    let content = match fs::read_to_string(path) {
        Ok(c) => c,
        Err(_) => return Ok(()), // Skip files that can't be read
    };

    for (line_number, line) in content.lines().enumerate() {
        for mat in regex.find_iter(line) {
            let match_obj = Match {
                file_path: path.clone(),
                line_number: line_number + 1,
                line_text: line.to_string(),
                match_start: mat.start(),
                match_end: mat.end(),
            };
            matches.push(match_obj);
        }
    }

    Ok(())
}

fn search_directory(path: &PathBuf, regex: &Regex, matches: &mut Vec<Match>, args: &Args) -> Result<()> {
    let walker = WalkDir::new(path)
        .into_iter()
        .filter_map(|e| e.ok());

    for entry in walker {
        let path = entry.path();

        if path.is_file() {
            search_file(&path.to_path_buf(), regex, matches, args)?;
        }
    }

    Ok(())
}

fn should_search_file(path: &PathBuf, args: &Args) -> bool {
